"""Visual judgement has evidence and constraints, not a single preferred aesthetic answer."""
REVIEWS = {
'R01': dict(finding='只堆风格词的题不能检验沟通，初学课也不应先考材质API。', decision='自己选参考中借鉴与不借鉴的特征，把感受译成可观察要求。', ai='把用户已提供参考拆成形状、比例、颜色、光照、表面候选描述，不猜未见图片。', proof=['对同一小屋的两份示意方案指出可见差异，分别用五维词汇表达。','写两项保留、一项排除和一个观察目标，再把规则用于路牌。'], diagnostic=('你要求柔和绘本小屋，AI给出圆润但油亮的玩具屋。当前只有这张实际结果图；参考图还没提供。你会让AI猜大师风格，还是补哪项可见差异？给一句保留/修改/不照搬的指令。','保留认可的圆润比例，说明需更哑光、反射克制等可观察表面差异，并提供可用参考或反例；不假称AI已看参考，也不必背Roughness属性。','哪部分已经接近，哪部分不满意？','指令保留局部优点、指出可见差异与参考缺口；不以大师名或审美偏好定对错。'), target=2),
'R02': dict(finding='剪影练习要控制观察大小；漂亮近景不能证明游戏距离可辨。', decision='先按玩家距离判断大形/负形，再决定小细节是否值得。', ai='准备同尺寸剪影与近远对照，只改一个比例或结构间隙。', proof=['隐藏表面细节后辨认道具用途，并指出轮廓上的证据。','只改一处比例/间隙，在游戏大小复核识别，不靠添加纹理补救。'], diagnostic=('160像素宽的水壶缩略图里把手和壶身黏成黑团；AI添加花纹，近景好看但黑色剪影没变。先要改哪个层次，如何对照而不同时改变机位和大小？','先改把手间隙/轮廓或主比例，保持显示尺寸、机位和黑色模式；新旧同尺寸比较，再恢复材质，花纹不修剪影。','问题在涂黑后仍存在吗？','基于轮廓选大形变化；同尺寸对照及游戏距离证据。'), target=2),
'R03': dict(finding='全场鲜艳不等于焦点清楚，灰度工具也不应被当完整审美评分器。', decision='选择目标与背景的相对关系，不让AI替你宣布某色盘所有儿童都喜欢。', ai='给固定布局光照的两版配色及灰度/缩略对照，明确哪些数值属教学控件。', proof=['固定其他条件只改变色相、饱和或明暗中的一类，说明差异。','按风格卡选焦点并在彩色/灰度/缩略中比较，说明工具的局限。'], diagnostic=('星星和黄墙都很鲜艳；AI同时提高全场饱和度，仍难找到星星。保持温暖主题，你先改变哪一个局部关系？用什么观察证明目标改善而不是仅图更鲜艳？','可降低邻域背景竞争或改变局部明暗/色相对比，先选一项并固定布局光照；同尺寸看第一焦点及目标轮廓，灰度仅补明暗观察，不规定唯一色盘。','你要增强的是整图颜色，还是目标相对背景的区分？','提出受控局部对比且有观察目标；接受不同有依据的色彩方案。'), target=2),
'R04': dict(finding='收藏/相似度不是迁移证据；作品研习应有一个观察问题与新题材验证。', decision='选择一条可见原则和可用参考，区分灵感、具体复制及分发条件。', ai='根据已提供作品协助标注焦点与色块，只做局部研习建议，不编原作来源。', proof=['在实际可见作品中指出焦点及两条支持证据，不以收藏数量计分。','隐藏参考后在不同题材使用一条原则，解释保留规则与未照搬形象。'], diagnostic=('你收藏了30张森林图。AI据艺术家名字直接替你生成一条街，并称完成临摹训练；没有问你观察到了什么。怎样把练习缩成一图一问题，并检验原则能迁移到街道？','从实际可查看且使用条件合适的参考选一图，先自己指出焦点与支持关系；用少量体块研究一条原则，再隐藏图换街道题材。AI结果本身不证明自己的观察能力。','这次你能独立说出哪条可见原则？','有自述观察证据和新题材验证，不以复制像或生成精美替代。'), target=2),
'R05': dict(finding='造型打磨要先判断基底和可见收益，不让一次黑斑故障带入完整拓扑课程。', decision='比较基底差距/编辑成本，保留可回退源，在玩家距离选择改造重点。', ai='列少量局部改造与可撤销修改器方案，复杂坏基底允许推荐换用。', proof=['按目标、来源和可编辑性选基底，能回到原始版本。','依次打磨大形、结构与有限细节，在固定游戏机位展示收益。'], diagnostic=('箱子局部有黑斑。AI连续增加Subdivision层级，面数上升但黑斑仍在；目标只要圆润绘本道具。接下来先检查哪类原因，怎样避免把未知故障当细节不足？','先恢复到可比基线，分别检查面朝向/重叠几何/法线等候选，用最小对照而非继续加面；无需背全部修复工具，严重问题可比较换基底成本。','增加几何是否曾改善目标症状？','停止无效加细分，选择一个可检验原因与回退；以游戏可见收益决定投入。'), target=2),
'R06': dict(finding='同风格与同材质不能混同；离线展示与引擎实效要分别留证。', decision='指定共同色盘/细节规则，同时保留布、木、金属的材料差异。', ai='准备固定展示条件和可交换/需重建效果清单，不把复杂节点导出说成必然无损。', proof=['为三件不同材质物体说明共同风格与合理响应差异，单变量比较。','在固定展示和真实游戏观察条件核对效果实现路径，无法执行明确待验。'], diagnostic=('箱子、灯罩、布袋都被设成同一种强金属反射。AI称数值一致就风格统一；Blender展示图还使用了未核对导出支持的节点。你接受哪些共性，分别改什么并怎样验收？','可共享色盘和细节规则，不要求所有材料同金属响应；按物体用途局部调整并固定展示。对特殊节点核对交换或引擎重建路径，真实导入未测不算通过。','风格规则和表面材料是同一层吗？','保留风格共性而恢复材料差异；明确展示与引擎证据界限。'), target=1),
'R07': dict(finding='资源库元数据要支持下一次安全复用，而不是仅填写命名表。', decision='确认基底、变体和共享依赖，选择什么可发布、什么尚待验证。', ai='整理最少可检索字段及引用清单，生成变体方案前先显示影响范围。', proof=['在一个主资产和两变体之间说明共享与独立，并做单件影响测试。','从另一场景按元数据找到并试用资产，能找到源文件、许可、尺寸、版本与验证状态。'], diagnostic=('你更新主材质后已完成的两个庭院一起变色；库里只有final3名称，没有引用或版本记录。AI建议全库Make Unique。怎样先限定受影响对象，再保留有意共享并提供回退？','先查主材质被谁引用，冻结/保留原版，对需不同风格的变体局部独立或版本化；验证两个场景和回退，避免无差别复制所有纹理。','哪些对象本来就应该一起改变？','依据依赖与需求分离，样本回归和可追溯版本；不是全量复制口号。'), target=1),
'R08': dict(finding='美术结业应评价整体关系和复用过程，不按单件精细或大师相似度评分。', decision='选择一项最影响整体的偏差，按实际玩家观察和来源证据判断成品。', ai='按风格卡提出少量局部变体及样板到套件清单，不重做整张世界。', proof=['六件套件在同一游戏机位形成一致比例/光色/细节层级并保持目标可辨。','交实际观察、改造前后、来源及可复用边界；换道具后规则仍可说明。'], diagnostic=('六件道具各自预览很漂亮，合进庭院后路灯比房屋还高，反射强弱杂乱。AI要增加粒子和雾。先选哪一个整体关系问题，如何局部修改并证明没挡住主路？','先按风格卡选择最显著的比例或材质不一致一项，固定机位局部修，再实走主路和目标观察；粒子/雾不是比例修复。不同有理方案可接受，不以个人偏好判输赢。','先不看装饰效果，最大的关系偏差是什么？','选择一项高收益关系并做同条件对照与路径回归，留下过程与复用说明。'), target=1),
}
